CREATE TABLE IF NOT EXISTS "portfoliocache" (id SERIAL PRIMARY KEY,billed NUMERIC(14,2) NOT NULL DEFAULT 0,paid NUMERIC(14,2) NOT NULL DEFAULT 0,outstanding NUMERIC(14,2) NOT NULL DEFAULT 0,thismonth NUMERIC(14,2) NOT NULL DEFAULT 0,cachedat TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS "apiconfig" (id SERIAL PRIMARY KEY,key VARCHAR(128) UNIQUE NOT NULL,value TEXT NOT NULL,updatedat TIMESTAMP NOT NULL DEFAULT NOW());
